    16	package hotel.documents;
    17	
    18	import hotel.reservations.Reservation;
    19	import hotel.rooms.Room;
    20	import hotel.rooms.RoomType;
    21	import java.math.BigDecimal;
    22	import java.time.LocalDate;
    23	
    24	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
    25	public record ReservationReceipt(
    26	        String title,
    27	        long reservationId,
    28	        String guestName,
    29	        String guestCpf,
    30	        int roomNumber,
    31	        RoomType roomType,
    32	        LocalDate checkIn,
    33	        LocalDate checkOut,
    34	        int nights,
    35	        BigDecimal subtotal,
    36	        BigDecimal discount,
    37	        BigDecimal total) {
    38	
    39	    public ReservationReceipt(Reservation reservation, Room room) {
    40	        this(
    41	                "Comprovante de reserva",
    42	                reservation.id(),
    43	                reservation.guest().name(),
    44	                reservation.guest().cpf(),
    45	                room.number(),
    46	                room.type(),
    47	                reservation.checkIn(),
    48	                reservation.checkOut(),
    49	                reservation.price().nights(),
    50	                reservation.price().subtotal(),
    51	                reservation.price().discount(),
    52	                reservation.price().total());
    53	    }
    54	
    55	    public String text() {
    56	        StringBuilder text = new StringBuilder();
    57	        text.append(title).append(" nº ").append(reservationId).append('\n');
    58	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
    59	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    60	        text.append("Entrada: ").append(TextFormat.date(checkIn))
    61	                .append(" | Saída: ").append(TextFormat.date(checkOut))
    62	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    63	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
    64	        if (discount.signum() > 0) {
    65	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
    66	        }
    67	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
    68	        return text.toString();
    69	    }
    70	}
    71	package hotel.web;
