    83	import hotel.reservations.NewReservation;
    84	import hotel.reservations.ReservationService;
    85	import hotel.rooms.Rooms;
    86	import io.javalin.Javalin;
    87	import io.javalin.http.Context;
    88	import io.javalin.json.JavalinJackson;
    89	import java.time.LocalDate;
    90	import java.time.YearMonth;
    91	import java.time.format.DateTimeParseException;
    92	
    93	/** The HTTP API the inn's website and front desk call. */
    94	public final class HttpApi {
    95	
    96	    private final Javalin server;
    97	    private final Rooms rooms;
    98	    private final ReservationService reservations;
    99	    private final SentMessages sentMessages;
   100	    private final OccupancyReport occupancyReport;
   101	    private final RevenueReport revenueReport;
   102	
   103	    public HttpApi(
   104	            Rooms rooms,
   105	            ReservationService reservations,
   106	            SentMessages sentMessages,
   107	            OccupancyReport occupancyReport,
   108	            RevenueReport revenueReport) {
   109	        this.rooms = rooms;
   110	        this.reservations = reservations;
   111	        this.sentMessages = sentMessages;
   112	        this.occupancyReport = occupancyReport;
   113	        this.revenueReport = revenueReport;
   114	
   115	        ObjectMapper jsonMapper = JsonMapper.builder()
   116	                .addModule(new JavaTimeModule())
   117	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
   118	                .build();
   119	        this.server = Javalin.create(config -> {
   120	            config.showJavalinBanner = false;
   121	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
   122	        });
   123	        registerRoutes();
   124	        registerErrorHandling();
   125	    }
   126	
   127	    public Javalin server() {
   128	        return server;
   129	    }
   130	
   131	    private void registerRoutes() {
   132	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
   133	
   134	        server.post("/reservations", ctx -> {
   135	            NewReservation request = readNewReservation(ctx);
   136	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
   137	        });
   138	        server.get("/reservations/{id}", ctx ->
   139	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
   140	        server.post("/reservations/{id}/confirmation", ctx ->
   141	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
   142	        server.post("/reservations/{id}/cancellation", ctx ->
   143	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
   144	        server.post("/reservations/{id}/check-in", ctx ->
   145	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
   146	        server.post("/reservations/{id}/check-out", ctx ->
   147	                ctx.json(reservations.checkOut(reservationId(ctx))));
   148	        server.get("/reservations/{id}/document", ctx ->
   149	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
   150	
   151	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
   152	
   153	        server.get("/reports/occupancy", ctx -> {
   154	            LocalDate night = readDate(ctx);
   155	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
   156	        });
   157	        server.get("/reports/revenue", ctx -> {
   158	            YearMonth month = readMonth(ctx);
   159	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
   160	        });
   161	    }
   162	
   163	    private void registerErrorHandling() {
   164	        server.exception(HotelException.class, (exception, ctx) -> {
   165	            ctx.status(httpStatus(exception.errorCode()));
   166	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
   167	        });
   168	    }
   169	
